class Solution { private class DSU(n:Int){val parent=IntArray(n){it};val rank=IntArray(n);fun find(value:Int):Int{if(parent[value]!=value)parent[value]=find(parent[value]);return parent[value]};fun union(first:Int,second:Int){var a=find(first);var b=find(second);if(a==b)return;if(rank[a]<rank[b]){val temporary=a;a=b;b=temporary};parent[b]=a;if(rank[a]==rank[b])rank[a]++}};fun distanceLimitedPathsExist(n:Int,edgeList:Array<IntArray>,queries:Array<IntArray>):List<Boolean>{edgeList.sortBy{it[2]};val order=queries.indices.sortedBy{queries[it][2]};val answer=BooleanArray(queries.size);val dsu=DSU(n);var edgeIndex=0;for(queryIndex in order){val limit=queries[queryIndex][2];while(edgeIndex<edgeList.size&&edgeList[edgeIndex][2]<limit){dsu.union(edgeList[edgeIndex][0],edgeList[edgeIndex][1]);edgeIndex++};answer[queryIndex]=dsu.find(queries[queryIndex][0])==dsu.find(queries[queryIndex][1])};return answer.toList()} }
